package softprobe

import "encoding/hex"

// These are normal FILE5_41 compiler outputs, never patched .mgc records.
type TailFileDatabase struct {
	Sources  []string
	Compiled []string
}

type TailFileCase struct {
	Name      string          `json:"name"`
	DB        string          `json:"db"`
	Data      string          `json:"data"`
	After     string          `json:"after"`
	Operation string          `json:"operation"`
	Stage     string          `json:"stage"`
	Want      [4]OffsetResult `json:"want"`
}

func TailFileDatabases() map[string]TailFileDatabase {
	return map[string]TailFileDatabase{
		"last":       {Sources: []string{"-1 ubyte x last=%u\n!:mime application/x-tail-last\n0 default x no-tail\n!:mime application/x-no-tail\n"}, Compiled: []string{""}},
		"first":      {Sources: []string{"-64 ubyte x first=%u\n!:mime application/x-tail-first\n0 default x no-tail\n!:mime application/x-no-tail\n"}, Compiled: []string{""}},
		"offset":     {Sources: []string{"-64 offset x at\n!:mime application/x-tail-offset\n0 default x no-tail\n!:mime application/x-no-tail\n"}, Compiled: []string{""}},
		"sets":       {Sources: []string{"-1 ubyte =255 impossible\n", "-1 ubyte x last=%u\n!:mime application/x-tail-last\n0 default x no-tail\n!:mime application/x-no-tail\n"}, Compiled: []string{"", ""}},
		"text":       {Sources: []string{"0 string/t AB root\n>-1 ubyte x tail=%u\n!:mime application/x-tail-text\n"}, Compiled: []string{""}},
		"text-prior": {Sources: []string{"-1 ubyte =255 impossible\n0 string/t AB root\n>-1 ubyte x tail=%u\n!:mime application/x-tail-text\n"}, Compiled: []string{""}},
	}
}

